-- ----------------------------
-- Table structure for booking_bus
-- ----------------------------
DROP TABLE IF EXISTS `booking_bus`;
CREATE TABLE `booking_bus`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `bus_id` int NOT NULL,
  `seat_id` int NOT NULL,
  `siswa_id` int NOT NULL,
  `created_at` datetime NULL DEFAULT current_timestamp,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unik_siswa`(`siswa_id` ASC) USING BTREE,
  UNIQUE INDEX `unik_seat`(`seat_id` ASC) USING BTREE,
  UNIQUE INDEX `seat_id_2`(`seat_id` ASC) USING BTREE,
  UNIQUE INDEX `siswa_id_2`(`siswa_id` ASC) USING BTREE,
  INDEX `bus_id`(`bus_id` ASC) USING BTREE,
  INDEX `seat_id`(`seat_id` ASC) USING BTREE,
  INDEX `siswa_id`(`siswa_id` ASC) USING BTREE,
  CONSTRAINT `fk_booking_bus_bus` FOREIGN KEY (`bus_id`) REFERENCES `bus` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_booking_bus_seat` FOREIGN KEY (`seat_id`) REFERENCES `bus_seat` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_booking_bus_siswa` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 778 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

