-- ----------------------------
-- Table structure for booking_kamar
-- ----------------------------
DROP TABLE IF EXISTS `booking_kamar`;
CREATE TABLE `booking_kamar`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `kamar_id` int NULL DEFAULT NULL,
  `siswa_id` int NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT current_timestamp,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unik_siswa_kegiatan`(`kamar_id` ASC, `siswa_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 750 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

