-- ----------------------------
-- Table structure for bus_seat
-- ----------------------------
DROP TABLE IF EXISTS `bus_seat`;
CREATE TABLE `bus_seat`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `bus_id` int NOT NULL,
  `nomor_kursi` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `baris` int NULL DEFAULT NULL,
  `kolom` int NULL DEFAULT NULL,
  `posisi` enum('L1','L2','R1','R2','BACK') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `status` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT current_timestamp,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unik_bus_kursi`(`bus_id` ASC, `nomor_kursi` ASC) USING BTREE,
  INDEX `bus_id`(`bus_id` ASC) USING BTREE,
  CONSTRAINT `fk_bus_seat_bus` FOREIGN KEY (`bus_id`) REFERENCES `bus` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 4062 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

